class _NibExampleState extends State<NibExample> {
  bool active = false;
  final name = TextEditingController();
  final shake = NibShakeController();
  @override
  void dispose() {
    name.dispose();
    shake.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      SizedBox(
        width: 280,
        child: Column(
          children: [
            TextField(
              controller: name,
              decoration: InputDecoration(
                labelText: "Project name",
                errorText: active ? "Use at least @@distanceRound@@ characters" : null,
              ),
            ),
            NibShake(
              controller: shake,
              child: Text(active ? "Try a longer name" : "Ready to check"),
            ),
          ],
        ),
      ),
      const SizedBox(height: 24),
      TextButton(
        onPressed: () {
          setState(() => active = name.text.trim().length < @@distanceRound@@);
          if (active) shake.shake();
        },
        child: const Text('Try / replay'),
      ),
    ],
  );
}
