);

class NibExample extends StatefulWidget {
  const NibExample({super.key});
  @override
  State<NibExample> createState() => _NibExampleState();
}

class _NibExampleState extends State<NibExample>
    with SingleTickerProviderStateMixin {
  bool active = false;
  final position = MotionValue<double>(0);
  late final solver = SpringSolver(
    vsync: this,
    value: position,
    spring: NibSpringDescription.gentle,
  );
  @override
  void dispose() {
    solver.dispose();
    position.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      NibMotion(
        motionValues: NibMotionValues(translateX: position),
        child: const FlutterLogo(size: 64),
      ),
      const SizedBox(height: 24),
      TextButton(
        onPressed: () {
          solver.animateTo(target: position.value < 40 ? 80 : 0);
        },
        child: const Text('Try / replay'),
      ),
    ],
  );
}
