  'scroll|':
      r'''// Add nib_motion to your Flutter app, then paste into lib/main.dart.
// Minimal primitive example; Full example includes the preview controls.
import 'package:flutter/material.dart';
import 'package:nib_motion/nib_motion.dart';

void main() => runApp(
  const MaterialApp(
    home: Scaffold(body: Center(child: NibExample())),
  ),
);

class NibExample extends StatefulWidget {
  const NibExample({super.key});
  @override
  State<NibExample> createState() => _NibExampleState();
}

class _NibExampleState extends State<NibExample> {
  bool active = false;
  final scroll = ScrollController();
  late final bridge = ScrollMotionBridge(controller: scroll);
  late final travel = bridge.scrollY.mapRange([0, 400], [0, 100]);
  late final angle = bridge.scrollY.mapRange([0, 400], [0, .5]);
  @override
  void dispose() {
    angle.dispose();
    travel.dispose();
    bridge.dispose();
    scroll.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      SizedBox(
        height: 240,
        child: Column(
          children: [
            NibMotion(
              motionValues: NibMotionValues(
                translateX: travel,
                rotate: angle,
              ),
              child: const FlutterLogo(size: 64),
            ),
            Expanded(
              child: ListView(
                controller: scroll,
                children: const [
                  SizedBox(
                    height: 600,
                    child: Text("Scroll to move the logo"),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
      const SizedBox(height: 24),
      TextButton(
        onPressed: () {
          setState(() => active = !active);
        },
        child: const Text('Try / replay'),
      ),
    ],
  );
}
